"""Classify one grain image. Usage: python src/predict.py path/to/"Basmati (12).jpg"
Exit 2: image unreadable or not 250x250 RGB. Exit 3: a trained-model file is missing."""
import json, re, sys
from pathlib import Path
import numpy as np
import common as C


def fail(code, msg):
    print(msg, file=sys.stderr)
    sys.exit(code)


def load_image(p):
    from PIL import Image
    try:
        im = Image.open(p)
        im.load()
    except Exception as e:
        fail(2, f"cannot read image {p}: {e}")
    if im.mode != "RGB" or im.size != (250, 250):
        fail(2, f"{p}: expected a 250x250 RGB image, got {im.size[0]}x{im.size[1]} {im.mode}")
    return np.asarray(im)


def need(*paths):
    for p in paths:
        if not Path(p).exists():
            fail(3, f"missing trained-model file: {p}. Run `make train`, then `make fit`.")


def table_row(name):
    """Table row of a file named `<Class> (<file_no>).jpg`, or None. Read directly, never through the gated test loader, and without label columns."""
    m = re.match(r"^(\w+) \((\d+)\)\.jpg$", name)
    if not m or not (C.DERIVED / "grains.parquet").exists(): return None
    import pandas as pd
    g = pd.read_parquet(C.DERIVED / "grains.parquet", columns=["grain_id", *C.ALL106])
    g = g[g.grain_id == f"{m.group(1)}-{m.group(2)}"]
    return g.iloc[[0]] if len(g) else None


def main():
    if len(sys.argv) != 2:
        fail(2, "usage: python src/predict.py <image.jpg>")
    path = Path(sys.argv[1])
    img = load_image(path)
    M = C.MODELS
    need(M / "cnn_seed0.pt", M / "routing.json", M / "gate_image.joblib", M / "gate_table.joblib", M / "hgb_all106.joblib")
    import joblib
    R = json.loads((M / "routing.json").read_text())
    model, mean, std = C.load_cnn(M / "cnn_seed0.pt")
    Pc, E = C.run_cnn(model, mean, std, lambda a, b: C.resize128(img)[None], 1)
    Pc = C.apply_temp(Pc, R["cnn"]["temperature"])
    unf_i = bool(joblib.load(M / "gate_image.joblib").unfamiliar(E)[0])

    row = table_row(path.name)

    print(f"image: {path.name}")
    print(f"image side: {C.CLASSES[int(Pc.argmax())]} (confidence {Pc.max():.4f})")
    unf_t, Ph = False, None
    if row is not None:
        X = row[C.ALL106].to_numpy(np.float64)
        Ph = C.apply_temp(joblib.load(M / "hgb_all106.joblib")["pipe"].predict_proba(row[C.ALL106]), R["hgb"]["temperature"])
        unf_t = bool(joblib.load(M / "gate_table.joblib").unfamiliar(X)[0])
        print(f"table side: {C.CLASSES[int(Ph.argmax())]} (confidence {Ph.max():.4f})")
    else:
        print("table side: no table row for this image")
    if unf_t or unf_i:
        route, ans, conf = "unfamiliar", None, None
    elif Ph is not None and Ph.max() >= R["hgb"]["floor"]:
        route, ans, conf = "hgb", int(Ph.argmax()), float(Ph.max())
    elif Pc.max() >= R["cnn"]["floor"]:
        route, ans, conf = "cnn", int(Pc.argmax()), float(Pc.max())
    else:
        route, ans, conf = "unsure", None, None
    print(f"route: {route}")
    print(f"familiarity: {'unfamiliar' if (unf_t or unf_i) else 'familiar'} (table gate {unf_t}, image gate {unf_i})")
    if ans is None:
        print("answer: none (" + ("this grain looks unlike the training grains" if route == "unfamiliar" else "not confident enough") + ")")
    else:
        print(f"answer: {C.CLASSES[ans]} (confidence {conf:.4f})")


if __name__ == "__main__":
    main()
